import"./chunk-VC46IEJQ.js";var e={group:"dorne",places:[{id:"sunspear",summary:{en:"The ancient seat of House Martell, built where a rocky spit of land juts into the sea at Dorne's eastern end. Its Spear Tower, the Tower of the Sun and the Threefold Gate look down on the crowded mud-brick sprawl of the shadow city. Since Nymeria's Rhoynar landed here a thousand years ago, Sunspear has ruled all Dorne.",zh:"\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u7684\u53E4\u8001\u5C45\u57CE\uFF0C\u5EFA\u5728\u591A\u6069\u4E1C\u7AEF\u4E00\u9053\u4F38\u5165\u5927\u6D77\u7684\u5CA9\u77F3\u5CAC\u89D2\u4E0A\u3002\u957F\u77DB\u5854\u3001\u592A\u9633\u5854\u4E0E\u4E09\u91CD\u95E8\u4FEF\u77B0\u7740\u57CE\u4E0B\u62E5\u6324\u6742\u4E71\u7684\u6CE5\u7816\u8857\u5DF7\u2014\u2014\u5F71\u5B50\u57CE\u3002\u81EA\u5343\u5E74\u524D\u5A1C\u6885\u8389\u4E9A\u7387\u6D1B\u4F0A\u62FF\u4EBA\u5728\u6B64\u767B\u9646\uFF0C\u9633\u621F\u57CE\u4FBF\u7EDF\u6CBB\u7740\u6574\u4E2A\u591A\u6069\u3002"},houses:["martell"],refs:["agot","affc","adwd","twoiaf"],confidence:"high"},{id:"shadow-city",kind:"town",region:"dorne",at:[603,1272],rank:2,names:{en:"The Shadow City",zh:"\u5F71\u5B50\u57CE"},alt:["Shadow City","Sunspear town"],summary:{en:"The tangle of mud-brick hovels, shops and alleys that grew up beneath Sunspear's walls. Its narrow lanes are shaded by the castle itself, hence the name; three successive walls must be passed to reach the Old Palace.",zh:"\u5728\u9633\u621F\u57CE\u57CE\u5899\u4E0B\u9010\u6E10\u957F\u6210\u7684\u4E00\u7247\u6CE5\u7816\u964B\u5C4B\u3001\u5E97\u94FA\u4E0E\u7A84\u5DF7\u3002\u8857\u5DF7\u7EC8\u65E5\u7B3C\u7F69\u5728\u57CE\u5821\u7684\u9634\u5F71\u4E4B\u4E2D\uFF0C\u6545\u5F97\u6B64\u540D\uFF1B\u8981\u62B5\u8FBE\u65E7\u738B\u5BAB\uFF0C\u987B\u5148\u7A7F\u8FC7\u5C42\u5C42\u57CE\u5899\u3002"},houses:["martell"],refs:["affc","twoiaf"],confidence:"high"},{id:"water-gardens",kind:"castle",region:"dorne",at:[594,1291],rank:3,names:{en:"The Water Gardens",zh:"\u6D41\u6C34\u82B1\u56ED"},alt:["Water Gardens","\u6C34\u4E4B\u82B1\u56ED"],summary:{en:"A pink-marble pleasure palace of fountains, pools and orange trees a few leagues west of Sunspear by the sea. A Martell prince built it for his Targaryen bride; today children of nobles and commoners alike play in its pools together. Prince Doran retires here to nurse his gout.",zh:"\u9633\u621F\u57CE\u4EE5\u897F\u6570\u91CC\u683C\u3001\u4E34\u6D77\u800C\u5EFA\u7684\u7C89\u8272\u5927\u7406\u77F3\u79BB\u5BAB\uFF0C\u904D\u5E03\u55B7\u6CC9\u3001\u6C34\u6C60\u4E0E\u6A59\u6811\u3002\u5F53\u5E74\u4E00\u4F4D\u9A6C\u6CF0\u5C14\u4EB2\u738B\u4E3A\u8FCE\u5A36\u5766\u683C\u5229\u5B89\u65B0\u5A18\u800C\u5EFA\uFF1B\u5982\u4ECA\u8D35\u65CF\u4E0E\u5E73\u6C11\u7684\u5B69\u5B50\u4E00\u540C\u5728\u6C60\u4E2D\u5B09\u6C34\u3002\u9053\u6717\u4EB2\u738B\u4E3A\u75DB\u98CE\u6240\u82E6\uFF0C\u5E38\u907F\u5C45\u4E8E\u6B64\u3002"},houses:["martell"],refs:["affc","adwd","twoiaf"],confidence:"high"},{id:"planky-town",kind:"town",region:"dorne",at:[598,1262],rank:3,names:{en:"Planky Town",zh:"\u6728\u677F\u9547"},summary:{en:"A floating town at the mouth of the Greenblood, made of barges, poleboats and hulks lashed together with planks and ropes. It is Dorne's busiest port for ships from the Free Cities, and the Orphans of the Greenblood ply the river above it.",zh:'\u7EFF\u8840\u6CB3\u53E3\u4E00\u5EA7\u6F02\u6D6E\u7684\u57CE\u9547\uFF0C\u7531\u9A73\u8239\u3001\u6491\u7BD9\u8239\u4E0E\u5E9F\u8239\u4EE5\u6728\u677F\u548C\u7EF3\u7D22\u8FDE\u7F00\u800C\u6210\u3002\u5B83\u662F\u591A\u6069\u8FCE\u63A5\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u8239\u53EA\u6700\u7E41\u5FD9\u7684\u6E2F\u53E3\uFF0C"\u7EFF\u8840\u5B64\u513F"\u4EEC\u5C31\u5728\u5176\u4E0A\u6E38\u7684\u6CB3\u9762\u5F80\u6765\u6491\u8239\u3002'},houses:["martell"],refs:["affc","adwd","twoiaf"],confidence:"high"},{id:"lemonwood",kind:"castle",region:"dorne",at:[626,1218],rank:2,names:{en:"Lemonwood",zh:"\u67E0\u6AAC\u6797\u57CE"},summary:{en:`Seat of House Dalt in eastern Dorne, not far from Sunspear; its name recalls the lemon groves around it. Ser Andrey "Drey" Dalt, heir to Lemonwood, is one of Princess Arianne's closest companions.`,zh:'\u6234\u5C14\u7279\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u591A\u6069\u4E1C\u90E8\u3001\u79BB\u9633\u621F\u57CE\u4E0D\u8FDC\uFF0C\u56E0\u5468\u56F4\u7684\u67E0\u6AAC\u6797\u800C\u5F97\u540D\u3002\u67E0\u6AAC\u6797\u7684\u7EE7\u627F\u4EBA\u5B89\u5FB7\u96F7\uFF08"\u5FB7\u96F7"\uFF09\xB7\u6234\u5C14\u7279\u7235\u58EB\u662F\u4E9A\u83B2\u6069\u516C\u4E3B\u6700\u4EB2\u5BC6\u7684\u4F19\u4F34\u4E4B\u4E00\u3002'},houses:["dalt"],refs:["affc","twoiaf"],confidence:"low"},{id:"godsgrace",kind:"castle",region:"dorne",at:[480,1238],rank:3,names:{en:"Godsgrace",zh:"\u795E\u6069\u57CE"},summary:{en:"Seat of House Allyrion where the Brimstone and the Vaith join to form the Greenblood. The surrounding river valley is some of the most fertile land in Dorne, a green strip between the sands.",zh:"\u827E\u5229\u6602\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u786B\u78FA\u6CB3\u4E0E\u7EF4\u65AF\u6CB3\u4EA4\u6C47\u3001\u6C47\u6210\u7EFF\u8840\u6CB3\u4E4B\u5904\u3002\u5468\u56F4\u7684\u6CB3\u8C37\u662F\u591A\u6069\u6700\u80A5\u6C83\u7684\u571F\u5730\u4E4B\u4E00\uFF0C\u5728\u9EC4\u6C99\u4E4B\u95F4\u94FA\u5F00\u4E00\u6761\u7EFF\u5E26\u3002"},houses:["allyrion"],refs:["affc","twoiaf","maps"],confidence:"medium"},{id:"shandystone",kind:"ruin",region:"dorne",at:[520,1270],rank:2,names:{en:"Shandystone",zh:"\u6C99\u8FEA\u77F3\u57CE"},alt:["\u6C99\u8FEA\u77F3"],summary:{en:"An abandoned castle in the sands, once watered by a well that has long since run dry. Princess Arianne's party rests among its ruins while carrying Myrcella Baratheon toward the Greenblood.",zh:"\u9EC4\u6C99\u4E2D\u4E00\u5EA7\u8352\u5E9F\u7684\u57CE\u5821\uFF0C\u6614\u65E5\u8D56\u4EE5\u7EF4\u751F\u7684\u6C34\u4E95\u65E9\u5DF2\u5E72\u6DB8\u3002\u4E9A\u83B2\u6069\u516C\u4E3B\u4E00\u884C\u62A4\u9001\u5F25\u8D5B\u83C8\xB7\u62DC\u62C9\u5E2D\u6069\u524D\u5F80\u7EFF\u8840\u6CB3\u65F6\uFF0C\u66FE\u5728\u5176\u5E9F\u589F\u4E2D\u6B47\u811A\u3002"},spoiler:{en:"Arianne's scheme to crown Myrcella ends at the Greenblood soon after: Areo Hotah intercepts them, Ser Arys Oakheart is killed and Myrcella is maimed by Darkstar.",zh:"\u4E9A\u83B2\u6069\u62E5\u7ACB\u5F25\u8D5B\u83C8\u7684\u5BC6\u8C0B\u5728\u79BB\u5F00\u6B64\u5730\u540E\u4E0D\u4E45\u4FBF\u4E8E\u7EFF\u8840\u6CB3\u7554\u544A\u7EC8\uFF1A\u4F55\u5854\u622A\u4F4F\u4E86\u4ED6\u4EEC\uFF0C\u4E9A\u5386\u65AF\xB7\u5965\u514B\u8D6B\u7279\u7235\u58EB\u4E27\u547D\uFF0C\u5F25\u8D5B\u83C8\u88AB\u6697\u661F\u780D\u4F24\u6BC1\u5BB9\u3002"},houses:[],refs:["affc"],confidence:"low"},{id:"salt-shore",kind:"castle",region:"dorne",at:[520,1314],rank:2,names:{en:"Salt Shore",zh:"\u76D0\u6EE8\u57CE"},alt:["Saltshore"],summary:{en:"Seat of House Gargalen on Dorne's southern coast facing the Summer Sea. Lord Tremond Gargalen is among the Dornish lords who come to Sunspear in the time of Myrcella's stay.",zh:"\u76D6\u52A0\u4F26\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u591A\u6069\u5357\u90E8\u6D77\u5CB8\u3001\u9762\u671D\u590F\u65E5\u4E4B\u6D77\u3002\u7279\u8499\u5FB7\xB7\u76D6\u52A0\u4F26\u5927\u4EBA\u662F\u5F25\u8D5B\u83C8\u5BC4\u5C45\u591A\u6069\u671F\u95F4\u524D\u6765\u9633\u621F\u57CE\u7684\u591A\u6069\u9886\u4E3B\u4E4B\u4E00\u3002"},houses:["gargalen"],refs:["affc","twoiaf","maps"],confidence:"medium"},{id:"ghost-hill",kind:"castle",region:"dorne",at:[586,1198],rank:2,names:{en:"Ghost Hill",zh:"\u9B3C\u4E18\u57CE"},alt:["\u9B3C\u4E18"],summary:{en:"Seat of House Toland, whose heraldry shows a dragon devouring its own tail. Its position near the Sea of Dorne coast here is approximate.",zh:"\u6258\u5170\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5176\u7EB9\u7AE0\u662F\u4E00\u6761\u54AC\u4F4F\u81EA\u5DF1\u5C3E\u5DF4\u7684\u9F99\u3002\u6B64\u5904\u6807\u6CE8\u5728\u591A\u6069\u6D77\u6CBF\u5CB8\u9644\u8FD1\uFF0C\u4F4D\u7F6E\u4E3A\u8FD1\u4F3C\u3002"},houses:["toland"],refs:["affc","twoiaf"],confidence:"low"},{id:"spottswood",kind:"castle",region:"dorne",at:[528,1196],rank:2,names:{en:"Spottswood",zh:"\u6591\u6797\u57CE"},summary:{en:`Seat of House Santagar. Its heir, "Spotted Sylva" Santagar, is one of Princess Arianne's confidantes. The books say little of the castle itself, and its placement here on the Sea of Dorne side is a guess.`,zh:'\u6851\u5854\u52A0\u5BB6\u65CF\u7684\u5C45\u57CE\u3002\u5176\u7EE7\u627F\u4EBA"\u6591\u70B9"\u5E2D\u5C14\u5A03\xB7\u6851\u5854\u52A0\u662F\u4E9A\u83B2\u6069\u516C\u4E3B\u7684\u5FC3\u8179\u4E4B\u4E00\u3002\u4E66\u4E2D\u5BF9\u57CE\u5821\u672C\u8EAB\u7740\u58A8\u6781\u5C11\uFF0C\u6B64\u5904\u5C06\u5176\u6807\u5728\u591A\u6069\u6D77\u4E00\u4FA7\uFF0C\u7EAF\u5C5E\u63A8\u6D4B\u3002'},houses:["santagar"],refs:["affc"],confidence:"low"},{id:"hellholt",kind:"castle",region:"dorne",at:[446,1210],rank:2,names:{en:"Hellholt",zh:"\u5730\u72F1\u5821"},summary:{en:"Seat of House Uller on the Brimstone, a river whose waters stink of sulphur. The Ullers have a name for wildness; Ellaria Sand, Prince Oberyn's paramour, is the natural daughter of Lord Harmen Uller.",zh:"\u4E4C\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u6CB3\u6C34\u6563\u53D1\u786B\u78FA\u81ED\u5473\u7684\u786B\u78FA\u6CB3\u7554\u3002\u4E4C\u52D2\u5BB6\u7684\u4EBA\u7D20\u4EE5\u72C2\u91CE\u8457\u79F0\uFF1B\u5965\u67CF\u4F26\u4EB2\u738B\u7684\u60C5\u4EBA\u827E\u62C9\u8389\u4E9A\xB7\u6C99\u5FB7\u4FBF\u662F\u54C8\u8499\xB7\u4E4C\u52D2\u5927\u4EBA\u7684\u79C1\u751F\u5973\u3002"},houses:["uller"],refs:["asos","affc","twoiaf"],confidence:"medium"},{id:"vaith",kind:"castle",region:"dorne",at:[402,1270],rank:2,names:{en:"Vaith",zh:"\u7EF4\u65AF"},alt:["\u7EF4\u65AF\u57CE"],summary:{en:"Seat of House Vaith in the deep sands, on the upper reaches of the river of the same name. Little more than its lords' loyalty to Sunspear is recorded.",zh:"\u7EF4\u65AF\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u6DF1\u6C99\u4E4B\u4E2D\u3001\u540C\u540D\u6CB3\u6D41\u7684\u4E0A\u6E38\u3002\u5173\u4E8E\u5B83\uFF0C\u4E66\u4E2D\u8BB0\u4E0B\u7684\u4E0D\u8FC7\u662F\u5176\u9886\u4E3B\u6548\u5FE0\u9633\u621F\u57CE\u800C\u5DF2\u3002"},houses:["vaith"],refs:["affc","twoiaf","maps"],confidence:"medium"},{id:"sandstone",kind:"castle",region:"dorne",at:[372,1240],rank:2,names:{en:"Sandstone",zh:"\u6C99\u77F3\u57CE"},summary:{en:"Seat of House Qorgyle in the western deep sands, among the harshest country in Dorne. Ser Gulian Qorgyle rides to King's Landing in Prince Oberyn's company.",zh:"\u79D1\u683C\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u897F\u90E8\u6DF1\u6C99\u4E4B\u4E2D\uFF0C\u662F\u591A\u6069\u6700\u4E25\u9177\u7684\u5730\u5E26\u4E4B\u4E00\u3002\u53E4\u91CC\u5B89\xB7\u79D1\u683C\u5C14\u7235\u58EB\u66FE\u968F\u5965\u67CF\u4F26\u4EB2\u738B\u4E00\u540C\u524D\u5F80\u541B\u4E34\u3002"},houses:["qorgyle"],refs:["asos","twoiaf","maps"],confidence:"medium"},{id:"tor",kind:"castle",region:"dorne",at:[334,1246],rank:2,names:{en:"The Tor",zh:"\u6258\u5C14\u57CE"},alt:["Tor"],summary:{en:"Seat of House Jordayne, near Dorne's south-western coast between Starfall and the deep sands. The Jordaynes bear a golden quill on their arms.",zh:"\u4E54\u6234\u6069\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u591A\u6069\u897F\u5357\u6D77\u5CB8\u9644\u8FD1\uFF0C\u4ECB\u4E8E\u661F\u5760\u57CE\u4E0E\u6DF1\u6C99\u4E4B\u95F4\u3002\u4E54\u6234\u6069\u5BB6\u65CF\u7684\u7EB9\u7AE0\u662F\u4E00\u652F\u91D1\u8272\u7FBD\u6BDB\u7B14\u3002"},houses:["jordayne"],refs:["affc","twoiaf","maps"],confidence:"medium"},{id:"starfall",kind:"castle",region:"dorne",at:[292,1222],rank:3,names:{en:"Starfall",zh:"\u661F\u5760\u57CE"},summary:{en:"Seat of House Dayne on an island where the Torrentine meets the Summer Sea. Legend says the Daynes' first lord followed a falling star to this spot and forged the sword Dawn from its heart. The finest Dayne knight of each generation bears Dawn as the Sword of the Morning.",zh:'\u6234\u6069\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u5750\u843D\u4E8E\u6FC0\u6D41\u6CB3\u6CE8\u5165\u590F\u65E5\u4E4B\u6D77\u5904\u7684\u4E00\u5EA7\u5C9B\u4E0A\u3002\u4F20\u8BF4\u6234\u6069\u5BB6\u7684\u59CB\u7956\u8FFD\u968F\u4E00\u9897\u5760\u843D\u7684\u661F\u8FB0\u6765\u5230\u6B64\u5730\uFF0C\u5E76\u4EE5\u5176\u661F\u6838\u953B\u9020\u4E86\u5B9D\u5251"\u9ECE\u660E"\u3002\u6BCF\u4E00\u4EE3\u4E2D\u6700\u51FA\u8272\u7684\u6234\u6069\u9A91\u58EB\u6267\u6B64\u5251\uFF0C\u88AB\u79F0\u4E3A"\u62C2\u6653\u795E\u5251"\u3002'},houses:["dayne"],refs:["agot","asos","affc","twoiaf"],confidence:"high"},{id:"high-hermitage",kind:"castle",region:"dorne",at:[308,1214],rank:2,names:{en:"High Hermitage",zh:"\u9AD8\u9690\u5E90"},summary:{en:"A small castle near Starfall held by a lesser branch of House Dayne. Its best-known son is Ser Gerold Dayne, called Darkstar, a dangerous knight with a streak of purple in his silver hair.",zh:'\u661F\u5760\u57CE\u9644\u8FD1\u7684\u4E00\u5EA7\u5C0F\u57CE\u5821\uFF0C\u7531\u6234\u6069\u5BB6\u65CF\u7684\u4E00\u4E2A\u65C1\u652F\u636E\u5B88\u3002\u6B64\u5730\u6700\u51FA\u540D\u7684\u5B50\u5F1F\u662F\u7EF0\u53F7"\u6697\u661F"\u7684\u6770\u6D1B\xB7\u6234\u6069\u7235\u58EB\u2014\u2014\u94F6\u53D1\u4E2D\u5939\u7740\u4E00\u7F15\u7D2B\u8272\u3001\u5371\u9669\u96BE\u6D4B\u7684\u9A91\u58EB\u3002'},houses:["dayne-of-high-hermitage"],refs:["affc","twoiaf"],confidence:"medium"},{id:"torrentine",kind:"river",region:"dorne",at:[298,1212],rank:2,names:{en:"The Torrentine",zh:"\u6FC0\u6D41\u6CB3"},alt:["Torrentine"],summary:{en:"A swift river that rushes down from the western Red Mountains to the Summer Sea, reaching it at Starfall. Its falls and rapids give it its name.",zh:"\u4E00\u6761\u6E4D\u6025\u7684\u6CB3\u6D41\uFF0C\u81EA\u8D64\u7EA2\u5C71\u8109\u897F\u6BB5\u5954\u6D41\u800C\u4E0B\uFF0C\u5728\u661F\u5760\u57CE\u6CE8\u5165\u590F\u65E5\u4E4B\u6D77\u3002\u5176\u540D\u6B63\u5F97\u81EA\u6CBF\u9014\u7684\u7011\u5E03\u4E0E\u6025\u6D41\u3002"},houses:["dayne"],refs:["affc","twoiaf","maps"],confidence:"medium"},{id:"red-mountains",kind:"mountain",region:"dorne",at:[420,1166],rank:4,names:{en:"The Red Mountains",zh:"\u8D64\u7EA2\u5C71\u8109"},alt:["Red Mountains","Dornish mountains"],summary:{en:"The rugged red-rock range that walls Dorne off from the Reach and the Stormlands. Only two practical roads cross it \u2014 the Prince's Pass in the west and the Boneway in the east \u2014 which is why Dorne alone resisted the Conqueror's dragons and armies for so long.",zh:"\u8D64\u8272\u5CA9\u77F3\u6784\u6210\u7684\u5D0E\u5C96\u5C71\u8109\uFF0C\u5C06\u591A\u6069\u4E0E\u6CB3\u6E7E\u5730\u3001\u98CE\u66B4\u5730\u9694\u5F00\u3002\u771F\u6B63\u53EF\u884C\u7684\u901A\u9053\u53EA\u6709\u4E24\u6761\u2014\u2014\u897F\u8FB9\u7684\u4EB2\u738B\u9698\u53E3\u4E0E\u4E1C\u8FB9\u7684\u9AB8\u9AA8\u8DEF\u2014\u2014\u8FD9\u6B63\u662F\u591A\u6069\u80FD\u957F\u671F\u62B5\u5FA1\u5F81\u670D\u8005\u7684\u5DE8\u9F99\u4E0E\u5927\u519B\u7684\u539F\u56E0\u3002"},houses:["yronwood","fowler","manwoody","blackmont","wyl"],refs:["agot","twoiaf","maps"],confidence:"high"},{id:"princes-pass",kind:"pass",region:"dorne",at:[318,1182],rank:3,names:{en:"Prince's Pass",zh:"\u4EB2\u738B\u9698\u53E3"},summary:{en:"The western road through the Red Mountains, linking the Reach's Dornish Marches to the sands. Skyreach and Kingsgrave guard its southern end, and invading armies have repeatedly come to grief in its narrows.",zh:"\u7A7F\u8D8A\u8D64\u7EA2\u5C71\u8109\u7684\u897F\u8DEF\uFF0C\u8FDE\u63A5\u6CB3\u6E7E\u5730\u4E00\u4FA7\u7684\u591A\u6069\u8FB9\u7586\u5730\u4E0E\u5357\u65B9\u7684\u6C99\u6F20\u3002\u5929\u53CA\u57CE\u4E0E\u738B\u5893\u627C\u5B88\u5176\u5357\u7AEF\uFF0C\u5165\u4FB5\u7684\u5927\u519B\u5C61\u5C61\u5728\u8FD9\u6761\u9669\u9053\u4E2D\u6298\u621F\u3002"},houses:["fowler","manwoody"],refs:["asos","twoiaf","maps"],confidence:"high"},{id:"skyreach",kind:"castle",region:"dorne",at:[324,1198],rank:2,names:{en:"Skyreach",zh:"\u5929\u53CA\u57CE"},summary:{en:"Seat of House Fowler, perched at the Dornish end of the Prince's Pass. The Fowlers, whose arms show a falcon, have long been the first Dornish lords any army coming down the pass must face.",zh:"\u4F5B\u52D2\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u9AD8\u8E1E\u4E8E\u4EB2\u738B\u9698\u53E3\u7684\u591A\u6069\u4E00\u7AEF\u3002\u4EE5\u730E\u9E70\u4E3A\u7EB9\u7AE0\u7684\u4F5B\u52D2\u5BB6\u65CF\uFF0C\u5386\u6765\u662F\u4EFB\u4F55\u4ECE\u9698\u53E3\u5357\u4E0B\u7684\u519B\u961F\u9996\u5148\u8981\u9762\u5BF9\u7684\u591A\u6069\u9886\u4E3B\u3002"},houses:["fowler"],refs:["asos","twoiaf","maps"],confidence:"medium"},{id:"kingsgrave",kind:"castle",region:"dorne",at:[350,1188],rank:2,names:{en:"Kingsgrave",zh:"\u738B\u5893"},alt:["\u738B\u5893\u57CE"],summary:{en:"Seat of House Manwoody in the Red Mountains near the Prince's Pass; its grim name, echoed by the crowned skull on the Manwoody arms, is said to recall a king who fell nearby. Lord Dagos Manwoody is a loyal bannerman of Sunspear.",zh:"\u66FC\u4F0D\u8FEA\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u4EB2\u738B\u9698\u53E3\u9644\u8FD1\u7684\u8D64\u7EA2\u5C71\u8109\u4E2D\uFF1B\u9634\u68EE\u7684\u57CE\u540D\u4E0E\u66FC\u4F0D\u8FEA\u7EB9\u7AE0\u4E0A\u90A3\u9897\u6234\u51A0\u9AB7\u9AC5\u76F8\u4E92\u547C\u5E94\uFF0C\u636E\u8BF4\u662F\u5728\u7EAA\u5FF5\u4E00\u4F4D\u6B92\u547D\u4E8E\u9644\u8FD1\u7684\u56FD\u738B\u3002\u8FBE\u6208\u65AF\xB7\u66FC\u4F0D\u8FEA\u5927\u4EBA\u662F\u9633\u621F\u57CE\u5FE0\u5B9E\u7684\u5C01\u81E3\u3002"},houses:["manwoody"],refs:["affc","twoiaf"],confidence:"medium"},{id:"blackmont",kind:"castle",region:"dorne",at:[384,1188],rank:2,names:{en:"Blackmont",zh:"\u9ED1\u5C71\u57CE"},summary:{en:"Seat of House Blackmont in the Red Mountains, whose arms show a black vulture clutching a babe. Lady Larra Blackmont and her daughter Jynessa travel to King's Landing with Prince Oberyn.",zh:"\u5E03\u83B1\u514B\u8499\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u4F4D\u4E8E\u8D64\u7EA2\u5C71\u8109\u4E4B\u4E2D\uFF0C\u5176\u7EB9\u7AE0\u662F\u4E00\u53EA\u722A\u652B\u5A74\u5B69\u7684\u9ED1\u79C3\u9E6B\u3002\u62C9\u62C9\xB7\u5E03\u83B1\u514B\u8499\u592B\u4EBA\u4E0E\u5973\u513F\u5409\u59AE\u838E\u66FE\u968F\u5965\u67CF\u4F26\u4EB2\u738B\u524D\u5F80\u541B\u4E34\u3002"},houses:["blackmont"],refs:["asos","twoiaf"],confidence:"medium"},{id:"tower-of-joy",kind:"ruin",region:"dorne",at:[356,1206],rank:2,names:{en:"The Tower of Joy",zh:"\u6781\u4E50\u5854"},alt:["Tower of Joy","\u559C\u60A6\u4E4B\u5854"],summary:{en:"A lone round tower in the Red Mountains, remembered in Eddard Stark's fevered dreams; Eddard later pulled it down and used its stones to raise eight cairns. Its exact position is never given in the books; the marker here is only a guess somewhere in the mountains.",zh:"\u8D64\u7EA2\u5C71\u8109\u4E2D\u4E00\u5EA7\u5B64\u96F6\u96F6\u7684\u5706\u5854\uFF0C\u5E38\u5728\u827E\u5FB7\xB7\u53F2\u5854\u514B\u7684\u68A6\u9B47\u4E2D\u51FA\u73B0\uFF1B\u540E\u6765\u827E\u5FB7\u5C06\u5B83\u62C6\u6BC1\uFF0C\u7528\u5176\u77F3\u5757\u5792\u8D77\u4E86\u516B\u5EA7\u575F\u51A2\u3002\u4E66\u4E2D\u4ECE\u672A\u8BF4\u660E\u5176\u786E\u5207\u4F4D\u7F6E\uFF0C\u6B64\u5904\u6807\u8BB0\u53EA\u662F\u5BF9\u5C71\u4E2D\u67D0\u5904\u7684\u731C\u6D4B\u3002"},spoiler:{en:`Rhaegar Targaryen named the tower. At the end of Robert's Rebellion Eddard and six companions fought three Kingsguard here, Ser Arthur Dayne among them; only Eddard and Howland Reed survived. Lyanna Stark was found inside, dying "in a bed of blood" \u2014 what she made Ned promise is one of the series' central mysteries.`,zh:'\u6B64\u5854\u7531\u96F7\u52A0\xB7\u5766\u683C\u5229\u5B89\u547D\u540D\u3002\u52B3\u52C3\u53DB\u4E71\u672B\u671F\uFF0C\u827E\u5FB7\u4E0E\u516D\u540D\u540C\u4F34\u5728\u6B64\u4E0E\u4E09\u540D\u5FA1\u6797\u94C1\u536B\uFF08\u5305\u62EC\u4E9A\u745F\xB7\u6234\u6069\u7235\u58EB\uFF09\u6B7B\u6218\uFF0C\u53EA\u6709\u827E\u5FB7\u4E0E\u970D\u5170\xB7\u9ECE\u5FB7\u751F\u8FD8\u3002\u83B1\u5B89\u5A1C\xB7\u53F2\u5854\u514B\u88AB\u53D1\u73B0\u8EBA\u5728\u5854\u4E2D\uFF0C"\u5728\u8840\u5E8A\u4E0A"\u5944\u5944\u4E00\u606F\u2014\u2014\u5979\u8BA9\u5948\u5FB7\u8BB8\u4E0B\u7684\u627F\u8BFA\uFF0C\u662F\u5168\u4E66\u7684\u6838\u5FC3\u8C1C\u56E2\u4E4B\u4E00\u3002'},houses:[],refs:["agot","asos"],confidence:"low"},{id:"yronwood",kind:"castle",region:"dorne",at:[430,1186],rank:3,names:{en:"Yronwood",zh:"\u94C1\u6728\u57CE"},summary:{en:"The great stronghold of House Yronwood on the southern slopes of the Red Mountains, near the Boneway. Before the Rhoynar came the Yronwoods were kings over much of Dorne, and they remain the most powerful \u2014 and least reconciled \u2014 of Sunspear's vassals.",zh:"\u4F0A\u4F26\u4F0D\u5FB7\u5BB6\u65CF\u7684\u575A\u56FA\u8981\u585E\uFF0C\u5750\u843D\u4E8E\u8D64\u7EA2\u5C71\u8109\u5357\u9E93\u3001\u9AB8\u9AA8\u8DEF\u9644\u8FD1\u3002\u6D1B\u4F0A\u62FF\u4EBA\u5230\u6765\u4E4B\u524D\uFF0C\u4F0A\u4F26\u4F0D\u5FB7\u5BB6\u65CF\u66FE\u662F\u591A\u6069\u5927\u7247\u571F\u5730\u4E4B\u738B\uFF0C\u81F3\u4ECA\u4ECD\u662F\u9633\u621F\u57CE\u9EBE\u4E0B\u6700\u5F3A\u5927\u3001\u4E5F\u6700\u5FC3\u5B58\u82A5\u8482\u7684\u5C01\u81E3\u3002"},houses:["yronwood"],refs:["adwd","twoiaf","maps"],confidence:"medium"},{id:"wyl",kind:"castle",region:"dorne",at:[470,1172],rank:2,names:{en:"Wyl",zh:"\u5A01\u5C14"},alt:["\u5A01\u5C14\u57CE"],summary:{en:"Seat of House Wyl, high in the Red Mountains along the Boneway. The Wyls have a dark name among stormlanders as mountain raiders who ambushed armies and travellers on the pass.",zh:"\u5A01\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\uFF0C\u9AD8\u8E1E\u4E8E\u8D64\u7EA2\u5C71\u8109\u3001\u9AB8\u9AA8\u8DEF\u6CBF\u7EBF\u3002\u5728\u98CE\u66B4\u5730\u4EBA\u53E3\u4E2D\uFF0C\u5A01\u5C14\u5BB6\u65CF\u662F\u51F6\u540D\u5728\u5916\u7684\u5C71\u5730\u52AB\u63A0\u8005\uFF0C\u60EF\u4E8E\u5728\u5C71\u8DEF\u4E0A\u4F0F\u51FB\u519B\u961F\u4E0E\u65C5\u4EBA\u3002"},houses:["wyl"],refs:["adwd","twoiaf"],confidence:"medium"},{id:"boneway",kind:"pass",region:"dorne",at:[488,1162],rank:3,names:{en:"The Boneway",zh:"\u9AB8\u9AA8\u8DEF"},alt:["Boneway","Stone Way"],summary:{en:"The eastern road over the Red Mountains, climbing from the Stormlands past Wyl to Yronwood. Its name comes from the bones of the many soldiers who have died along it in Dorne's wars.",zh:"\u7FFB\u8D8A\u8D64\u7EA2\u5C71\u8109\u7684\u4E1C\u8DEF\uFF0C\u4ECE\u98CE\u66B4\u5730\u51FA\u53D1\uFF0C\u7ECF\u5A01\u5C14\u57CE\u4E0B\u884C\u81F3\u94C1\u6728\u57CE\u3002\u5176\u540D\u6765\u81EA\u5386\u6B21\u591A\u6069\u6218\u4E89\u4E2D\u6B7B\u5728\u6CBF\u9014\u7684\u65E0\u6570\u58EB\u5175\u7684\u767D\u9AA8\u3002"},houses:["wyl","yronwood"],refs:["adwd","twoiaf","maps"],confidence:"high"},{id:"greenblood",kind:"river",region:"dorne",at:[536,1252],rank:3,names:{en:"The Greenblood",zh:"\u7EFF\u8840\u6CB3"},alt:["Greenblood"],summary:{en:"Dorne's only great river, formed at Godsgrace and flowing east through the sands to the sea at Planky Town. Nearly all of Dorne's farming clings to its banks, and the Orphans of the Greenblood \u2014 descendants of Rhoynar who still long for their lost river \u2014 pole their boats along it.",zh:'\u591A\u6069\u552F\u4E00\u7684\u5927\u6CB3\uFF0C\u5728\u795E\u6069\u57CE\u6C47\u6210\uFF0C\u5411\u4E1C\u7A7F\u8FC7\u6C99\u6F20\uFF0C\u4E8E\u6728\u677F\u9547\u5165\u6D77\u3002\u591A\u6069\u7684\u519C\u8015\u51E0\u4E4E\u5168\u90FD\u4F9D\u9644\u5728\u5B83\u4E24\u5CB8\uFF1B"\u7EFF\u8840\u5B64\u513F"\u2014\u2014\u4ECD\u5728\u6000\u5FF5\u6545\u571F\u6D1B\u6069\u6CB3\u7684\u6D1B\u4F0A\u62FF\u4EBA\u540E\u88D4\u2014\u2014\u5728\u6CB3\u4E0A\u6491\u7BD9\u5F80\u6765\u3002'},houses:["allyrion","martell"],refs:["affc","adwd","twoiaf","maps"],confidence:"high"},{id:"brimstone",kind:"river",region:"dorne",at:[462,1222],rank:2,names:{en:"The Brimstone",zh:"\u786B\u78FA\u6CB3"},alt:["Brimstone"],summary:{en:"A sulphurous river flowing down from the Red Mountains past Hellholt to join the Vaith at Godsgrace. Its yellow, foul-smelling water gives it its name.",zh:"\u4E00\u6761\u5E26\u7740\u786B\u78FA\u6C14\u5473\u7684\u6CB3\u6D41\uFF0C\u81EA\u8D64\u7EA2\u5C71\u8109\u6D41\u7ECF\u5730\u72F1\u5821\uFF0C\u5728\u795E\u6069\u57CE\u4E0E\u7EF4\u65AF\u6CB3\u6C47\u5408\u3002\u6CB3\u6C34\u6CDB\u9EC4\u800C\u8165\u81ED\uFF0C\u56E0\u6B64\u5F97\u540D\u3002"},houses:["uller"],refs:["twoiaf","maps"],confidence:"medium"},{id:"vaith-river",kind:"river",region:"dorne",at:[452,1246],rank:2,names:{en:"The Vaith",zh:"\u7EF4\u65AF\u6CB3"},summary:{en:"A thin desert river rising in the deep sands near the castle of Vaith and running east to Godsgrace, where it meets the Brimstone to form the Greenblood.",zh:"\u4E00\u6761\u7EC6\u7626\u7684\u6C99\u6F20\u6CB3\u6D41\uFF0C\u53D1\u6E90\u4E8E\u7EF4\u65AF\u57CE\u9644\u8FD1\u7684\u6DF1\u6C99\uFF0C\u5411\u4E1C\u6D41\u81F3\u795E\u6069\u57CE\uFF0C\u4E0E\u786B\u78FA\u6CB3\u6C47\u5408\u6210\u7EFF\u8840\u6CB3\u3002"},houses:["vaith"],refs:["twoiaf","maps"],confidence:"medium"},{id:"dornish-sands",kind:"desert",region:"dorne",at:[468,1290],rank:3,names:{en:"The Dornish sands",zh:"\u591A\u6069\u6C99\u6F20"},alt:["Deep sands","Dornish desert","\u6DF1\u6C99"],summary:{en:`The red and white sands that fill Dorne's heart, with the harshest "deep sands" in the west. Travellers cross them by night, from well to well, and the lords of the sand castles answer to Sunspear.`,zh:'\u586B\u6EE1\u591A\u6069\u8179\u5730\u7684\u7EA2\u767D\u6C99\u6D77\uFF0C\u897F\u90E8\u7684"\u6DF1\u6C99"\u6700\u4E3A\u4E25\u9177\u3002\u65C5\u4EBA\u591A\u5728\u591C\u95F4\u7A7F\u8D8A\uFF0C\u5FAA\u7740\u4E00\u53E3\u53E3\u6C34\u4E95\u524D\u884C\uFF1B\u5750\u843D\u5176\u95F4\u7684\u6C99\u6F20\u57CE\u5821\u9886\u4E3B\u7686\u542C\u547D\u4E8E\u9633\u621F\u57CE\u3002'},houses:["qorgyle","vaith","uller"],refs:["affc","twoiaf"],confidence:"high"},{id:"broken-arm",kind:"landmark",region:"dorne",at:[664,1212],rank:2,names:{en:"The Broken Arm",zh:"\u65AD\u81C2\u89D2"},alt:["Broken Arm","Arm of Dorne"],summary:{en:"The ragged peninsula at Dorne's north-eastern tip, pointing toward the Stepstones. Legend says it is what remains of the Arm of Dorne, the land bridge to Essos that the children of the forest shattered to stop the First Men.",zh:'\u591A\u6069\u4E1C\u5317\u7AEF\u53C2\u5DEE\u7684\u534A\u5C9B\uFF0C\u6307\u5411\u77F3\u9636\u5217\u5C9B\u3002\u4F20\u8BF4\u5B83\u662F"\u591A\u6069\u4E4B\u81C2"\u7684\u6B8B\u4F59\u2014\u2014\u90A3\u6761\u8FDE\u901A\u5384\u7D22\u65AF\u7684\u9646\u6865\uFF0C\u88AB\u68EE\u6797\u4E4B\u5B50\u51FB\u788E\u4EE5\u963B\u6321\u5148\u6C11\u3002'},houses:[],refs:["agot","twoiaf","maps"],confidence:"high"}]};export{e as default};
